catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading) {
      return;
   }
	if(newValue == ""){
		top.window.document.getElementById("poster_img").src = "";
	}
   top.window.document.getElementById("poster_img").src = g_form.getValue("poster_url");


}
